// Dates and qualitative tradeoffs follow manual pp.51–52,116. Numeric values are approximations.
export const POWER_PLANTS={coal:{name:'Coal power plant',size:4,year:1900,cost:5000,upkeep:60,capacity:500,air:48,water:32,sprite:9},oil:{name:'Oil power plant',size:4,year:1900,cost:5500,upkeep:65,capacity:400,air:35,water:24,sprite:35},gas:{name:'Gas power plant',size:3,year:1955,cost:8000,upkeep:70,capacity:350,air:16,water:8,sprite:36},nuclear:{name:'Nuclear power plant',size:4,year:1965,cost:15000,upkeep:100,capacity:1000,air:0,water:0,sprite:37},wind:{name:'Wind turbine',size:1,year:1980,cost:500,upkeep:4,capacity:25,air:0,water:0,sprite:38},solar:{name:'Solar power plant',size:4,year:1990,cost:12000,upkeep:130,capacity:600,air:0,water:0,sprite:39},microwave:{name:'Microwave power plant',size:4,year:2020,cost:25000,upkeep:160,capacity:1200,air:0,water:0,sprite:40},fusion:{name:'Fusion power plant',size:4,year:2050,cost:40000,upkeep:180,capacity:2000,air:0,water:0,sprite:41}};
export const plantCapacity=t=>POWER_PLANTS[t.type]?Math.round(POWER_PLANTS[t.type].capacity*(t.type==='wind'?1+(t.elevation||0)*.1:1)*Math.max(.15,1-Math.max(0,t.age-240)/480)):0;
// Guide: no overload explosions in months 1–18; certain by month 30.
// The intervening linear probability curve is our approximation.
export const overloadFailureRisk=months=>Math.max(0,Math.min(1,(months-18)/12));
export function overloadRoll(c,t){let h=Math.imul(c.seed+97,374761393)^Math.imul(c.month+1,668265263)^Math.imul(t.root+1,1274126177);h=Math.imul(h^(h>>>13),1274126177);return ((h^(h>>>16))>>>0)/4294967296;}
export function overloadStatus(t){const months=t.stress||0;if(!(t.plantLoad>1))return 'Within capacity';return months<18?`${18-months} months before failure risk begins`:`${Math.round(overloadFailureRisk(months+1)*100)}% failure risk next month if overload continues`;}
export function advancePower(c){const failures=[],n=Math.sqrt(c.tiles.length);for(const t of c.tiles)if(POWER_PLANTS[t.type]){t.age++;if(t.root===t.y*n+t.x){t.stress=(t.plantLoad||0)>1?t.stress+1:0;if(overloadRoll(c,t)<overloadFailureRisk(t.stress))failures.push(t);}}return failures;}
export function powerStats(c){const roots=c.tiles.filter(t=>POWER_PLANTS[t.type]&&t.root===t.y*Math.sqrt(c.tiles.length)+t.x);return{overloadedPlants:roots.filter(t=>t.plantLoad>1).length,powerCapacity:roots.reduce((n,t)=>n+plantCapacity(t),0),powerUpkeep:roots.reduce((n,t)=>n+POWER_PLANTS[t.type].upkeep,0)};}
